def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # A two-cell horizontal marker determines the row immediately above it;
    # draw the full-width separator in color 8 there.
    for r, row in enumerate(grid):
        if any(row[c] != 4 and row[c] == row[c+1] for c in range(w-1)):
            if r > 0:
                out[r-1] = [8] * w
            break
    return out
